local action = os.getenv("HOME").."/.local/bin/caelestia-desktop "
local armed = false
hl.on("input.keyboard.key", function(code, timestamp, state)
    if code ~= 133 and state ~= 0 then armed = false end
end)
for _,button in ipairs({"mouse:272","mouse:273"}) do
    hl.bind(button,function() armed=false end,{transparent=true,non_consuming=true,ignore_mods=true,dont_inhibit=true,description="Mono: cancel Super tap on mouse press"})
end
mono = {}
function mono.detach(w)
    if w and w.group and w.group.size > 1 then
        hl.dispatch(hl.dsp.window.move({out_of_group=true,window=w}))
        hl.exec_scheduled_prop_refresh_immediately()
    end
end
function mono.minimize()
    local w=hl.get_active_window(); if not w then return end
    mono.detach(w)
    hl.dispatch(hl.dsp.window.tag({tag="+minimized",window=w}))
    hl.dispatch(hl.dsp.window.move({workspace="special:minimized",follow=false,window=w}))
end
function mono.restore()
    local w=hl.get_window("tag:minimized");local ws=hl.get_active_workspace()
    if not w or not ws then return end
    hl.dispatch(hl.dsp.window.move({workspace=ws,window=w}))
    hl.dispatch(hl.dsp.window.tag({tag="-minimized",window=w}))
    hl.dispatch(hl.dsp.focus({window=w}))
end
function mono.drag()
    mono.detach(hl.get_active_window());hl.dispatch(hl.dsp.window.drag())
end
function mono.resize()
    local w=hl.get_active_window()
    if w and not w.floating then
        local count=0
        for _,c in ipairs(hl.get_windows({workspace=w.workspace,floating=false})) do if c.visible then count=count+1 end end
        if count<=1 then
            hl.dispatch(hl.dsp.window.float({action="enable",window=w}))
            hl.exec_scheduled_prop_refresh_immediately()
        end
    end
    hl.dispatch(hl.dsp.window.resize())
end
